// A power history generated by point kinetics, through the validator, the case writer and (FEED_SOLVER=1) the real solver.
import { execFileSync } from "child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";
import { describe, expect, it } from "vitest";
import { writeOffbeatCase } from "../src/core/caseWriter";
import { RunBackend, RunManager } from "../src/core/runManager";
import { transientPreview } from "../src/core/transientPreview";
import { TransientResultsRecord, depositedEnergy } from "../src/core/transientResults";
import { validateCase } from "../src/core/validate";
import { WslBackend } from "../src/core/wslBackend";

const root = join(__dirname, "..");
const read = (p: string) => JSON.parse(readFileSync(join(root, p), "utf8"));
const example = () => read("examples/synthetic-pulse-kinetics.json");
const normalized = (doc: unknown) => {
  const v = validateCase(doc);
  expect(v.errors).toEqual([]);
  return v.normalized!;
};
const FUEL_AREA = Math.PI * 0.0041 ** 2;

describe("the generated history is an ordinary history to everything downstream", () => {
  const n = normalized(example());
  const g = n.transient!.generated!;

  it("the case is valid, the history replaces the placeholder, and qPrime is its peak", () => {
    expect(g).toBeDefined();
    expect(n.transient!.times).toEqual(g.times);
    expect(n.transient!.linearHeatRate).toEqual(g.linearHeatRate);
    expect(n.qPrime).toBe(Math.max(...g.linearHeatRate));
    expect(g.times[0]).toBe(0);
    expect(g.times[g.times.length - 1]).toBeCloseTo(0.06, 12);
  });

  it("the pulse is the size the Nordheim-Fuchs estimate gives for these numbers (peak about 168 MW, 10.8 ms wide, 265 K)", () => {
    expect(g.summary.peakPower / 1e6).toBeGreaterThan(160);
    expect(g.summary.peakPower / 1e6).toBeLessThan(175);
    expect(g.summary.fwhm! * 1e3).toBeGreaterThan(10.3);
    expect(g.summary.fwhm! * 1e3).toBeLessThan(11.3);
    expect(g.summary.peakFuelRise).toBeGreaterThan(255);
    expect(g.summary.peakFuelRise).toBeLessThan(275);
    expect(g.summary.insertedDollars).toBeCloseTo(3, 9);
  });

  it("the writer carries it as the power table, and says where it came from", () => {
    const w = writeOffbeatCase(n);
    expect(w.files["constant/solverDict"]).toMatch(/heatSource\s+timeDependentLhgr;/);
    const m = /lhgr\s+\(([^)]*)\)/.exec(w.files["constant/solverDict"]!)!;
    expect(m[1]!.trim().split(/\s+/).length).toBe(g.times.length + 1); // one flat point is appended past the end
    expect(w.mapping.find((x) => x.field === "transient.pointKinetics")!.note).toMatch(/generated/);
  });

  it("the preview carries the generator's summary and curve for the editor", () => {
    const p = transientPreview(n);
    expect(p.generator!.summary.peakPower).toBe(g.summary.peakPower);
    expect(p.generator!.curve.time.length).toBeLessThanOrEqual(401);
    expect(p.generator!.history.time).toEqual(g.times);
    expect(transientPreview(normalized(read("examples/synthetic-pulse.json"))).generator).toBeNull();
  });

  it("the adiabatic peak the preview states is the generator's own: 300 K plus the energy over the heat capacity", () => {
    const e = depositedEnergy(g.times, g.linearHeatRate, 0.06) / FUEL_AREA / 3e6;
    expect(transientPreview(n).adiabaticPeak).toBeCloseTo(300 + e, 6);
    expect(Math.abs(300 + e - (300 + g.summary.peakFuelRise))).toBeLessThan(0.5); // the history's energy is the integrated energy to 0.1%
  });

  it("validation is fast enough for an editor that validates as you type", () => {
    const t0 = Date.now();
    for (let i = 0; i < 5; i++) validateCase(example());
    expect((Date.now() - t0) / 5).toBeLessThan(150);
  });
});

describe("steady start and generator are one operating state", () => {
  it("a steady start at the generator's own initial heat rate is accepted and starts from that field", () => {
    const d = read("schema/vectors/good/pulse-point-kinetics-steady-start.json");
    const n = normalized(d);
    expect(n.transient!.initial).toEqual({ kind: "steady", linearHeatRate: 20 });
    expect(n.transient!.generated!.linearHeatRate[0]).toBeCloseTo(20, 9);
  });
  it("a steady start at another heat rate is refused with both numbers", () => {
    const e = validateCase(read("schema/vectors/bad/kinetics-steady-start-mismatch.json")).errors;
    expect(e).toHaveLength(1);
    expect(e[0]!.message).toMatch(/25 W\/m/);
    expect(e[0]!.message).toMatch(/gives 20 W\/m/);
  });
});

const solverOn = (() => {
  if (process.env.FEED_SOLVER !== "1" || process.platform !== "win32") return false;
  try {
    return execFileSync("wsl.exe", ["-l", "-q"], { encoding: "utf16le" }).split(/\r?\n/).some((l) => l.trim() === "feed-solver");
  } catch {
    return false;
  }
})();

class FaultyBackend implements RunBackend {
  inner = new WslBackend();
  constructor(private edit: (dict: string) => string) {}
  async run(args: Parameters<RunBackend["run"]>[0]) {
    const f = join(args.inputsDir, "constant", "solverDict");
    writeFileSync(f, this.edit(readFileSync(f, "utf8")));
    return this.inner.run(args);
  }
  cancel(id: string) {
    return this.inner.cancel(id);
  }
}
async function runCase(doc: unknown, backend: RunBackend = new WslBackend()) {
  const mgr = new RunManager({ runsRoot: mkdtempSync(join(tmpdir(), "feed-kin-")), backend, timeoutMs: 280_000 });
  const s = mgr.start(doc);
  if (!s.ok) throw new Error("start refused: " + JSON.stringify(s));
  const rec = await mgr.done(s.id);
  return { rec, res: mgr.results(s.id) as TransientResultsRecord | undefined };
}

describe.skipIf(!solverOn)("a generated pulse through the real solver (needs FEED_SOLVER=1)", () => {
  it("the example runs, every check passes, and the interior reaches the adiabatic value of the generated energy", async () => {
    const d = example();
    const { rec, res } = await runCase(d);
    expect(rec.state).toBe("completed");
    expect(res!.checks.map((c) => c.id)).toContain("pulseGenerator");
    expect(res!.checks.every((c) => c.verdict === "pass")).toBe(true);
    const g = normalized(d).transient!.generated!;
    const at = res!.times.findIndex((t) => Math.abs(t - 0.06) < 1e-9);
    const expected = 300 + depositedEnergy(g.times, g.linearHeatRate, 0.06) / FUEL_AREA / 3e6;
    expect(Math.abs(res!.profiles[at]![0]! - expected)).toBeLessThan(0.5); // the centre cell is adiabatic over the window
    expect(res!.generator!.summary.peakPower).toBe(g.summary.peakPower);
    expect(res!.generator!.curve.time.length).toBeGreaterThan(50);
  }, 300_000);

  it("the same pulse over 150 ms fails the generator check: the pin has lost 5% of the pulse's heat by then, which the lumped feedback did not see", async () => {
    const d = example();
    d.transient.endTime = { value: 150, unit: "ms" };
    d.transient.outputs = 30;
    const { rec, res } = await runCase(d);
    expect(rec.state).toBe("completed");
    const gen = res!.checks.find((c) => c.id === "pulseGenerator")!;
    expect(gen.verdict).toBe("fail");
    expect(gen.value!).toBeGreaterThan(10);
    expect(gen.value!).toBeLessThan(18); // measured 13.8 K
    expect(res!.checks.filter((c) => c.id !== "pulseGenerator").every((c) => c.verdict === "pass")).toBe(true);
  }, 300_000);

  it("a solver whose heat capacity is half the case's is caught by the generator check (and the cross-check)", async () => {
    const { res } = await runCase(example(), new FaultyBackend((dict) => dict.replace(/(Cp\s+Cp\s+\[0 2 -2 -1 0\]\s+)300;/, "$1150;")));
    expect(res!.checks.find((c) => c.id === "pulseGenerator")!.verdict).toBe("fail");
    expect(res!.checks.find((c) => c.id === "crossCheckFv")!.verdict).toBe("fail");
  }, 300_000);

  it("a steady start and the generator together: the pin starts from its 20 W/m state and the checks pass", async () => {
    const { rec, res } = await runCase(read("schema/vectors/good/pulse-point-kinetics-steady-start.json"));
    expect(rec.state).toBe("completed");
    expect(res!.initialState.kind).toBe("steady");
    expect(res!.checks.every((c) => c.verdict === "pass")).toBe(true);
  }, 300_000);
});
